values
  ('bc68f5c4-2104-4d62-95e5-1e74d6111fbe', 'zh', 'sechskies-hakwon-byeolgok', 'SECHSKIES《学院别曲》', '1997年SECHSKIES的反叛风格出道曲', 'SECHSKIES于1997年出道时推出的主打曲《学院别曲》，以批判应试教育现实的反叛歌词和强烈的舞台表现力，赢得了众多青少年的共鸣，与H.O.T.并称为韩国第一代偶像组合的代表。', 'SECHSKIES于1997年4月15日在KMTV《Show Music Tank》节目中以出道曲《学院别曲》首次亮相电视舞台，同年5月14日发行同名首张专辑。歌词正面批判以成绩至上主义为代表的应试教育问题，将韩国传统打令唱腔融入说唱的独特编曲，以及高难度杂技式团体舞蹈，在青少年群体中引发热议，并跻身歌谣排行榜前十。这首歌成为与H.O.T.形成第一代偶像两强格局的信号曲，也因是带有反叛信息的偶像出道曲而被认为影响了后来的组合。', '可作为第一代偶像出道曲的代表案例引用', null, array['学院别曲', '젝스키스 ''학원별곡''']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('aa390efd-1ba1-44c6-b493-2b046462ff4d', 'zh', 'looksam-hakkar-draw-quote', '呃~抽那么多牌的话…？', '룩삼(Looksam)使用哈卡尔卡组自我毁灭时留下的炉石传说名言', '2018年12月，炉石传说主播룩삼（金珍孝）在天梯对战中使用灵魂猎手哈卡尔卡组时，明知过度抽牌十分危险却停不下来，最终自我毁灭，并在过程中留下这句话。这句台词后来成为炉石传说粉丝圈中，用来形容“明知危险却停不下来”的代表性流行语。', '2018年12月主播룩삼（金珍孝）在炉石传说直播中的发言', '用于形容明知有风险却无法停止的情况', null, array['어~ 그렇게 드로우를 많이 하면?']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('8e975be3-2469-4c4a-a776-a84dbae6ed0b', 'zh', 'junggyeokma-unyielding-heart', '重要的是不被打倒的心（中挫马）', '2022年卡塔尔世界杯期间成为韩国国家队象征的助威口号', '这句原本流行于电竞粉丝圈的用语，在2022年11-12月卡塔尔世界杯小组赛中，韩国队在负于乌拉圭、加纳后仍绝地反击战胜葡萄牙、成功晋级16强的过程中，被用来形容代表队顽强不屈的精神而迅速传播开来。媒体、社交网络和各类广告纷纷以缩写“中挫马”反复引用，成为2022年下半年最具代表性的流行语。此后也被广泛用于运动、考试、求职等艰难处境中，表达不放弃的决心。', '2022年卡塔尔世界杯韩国队晋级16强过程中被重新关注的助威口号', '可用于任何人在艰难处境下表达不放弃决心或互相鼓励时使用', null, array['中挫马', '中挫马精神', '중요한 건 꺾이지 않는 마음']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
