values
  ('3840e458-bfec-497c-bd91-574ca6c4f019', 'zh', 'hwang-hee-chan-shirt-off-celebration', '黄喜灿脱衣庆祝', '2022世界杯对阵葡萄牙绝杀后黄喜灿脱掉球衣的庆祝动作', '在2022年卡塔尔世界杯小组赛末轮对阵葡萄牙的比赛伤停补时阶段，黄喜灿打入制胜球后脱掉上衣庆祝，因此吃到黄牌警告。凭借这粒进球，韩国队时隔12年再次晋级世界杯16强，该庆祝画面以及“奶牛”这一绰号也随之引发热议。', '2022年卡塔尔世界杯小组赛韩国对葡萄牙之战黄喜灿绝杀庆祝', '用于表达戏剧性胜利或痛快时刻', null, array['黄喜灿绝杀庆祝', '奶牛', '황희찬 웃통 탈의 세리머니']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
