values
  ('9266e072-5ccb-4386-99cd-14e631972eff', 'zh', 'baby-shark-challenge', '鲨鱼宝宝挑战', '跟跳Pinkfong《鲨鱼一家》舞蹈并上传社交网络的挑战', '2018年夏天，Pinkfong《鲨鱼一家（Baby Shark）》的舞蹈版本在美国和欧洲爆红，发展成连名人也参与的舞蹈挑战。艾伦·德杰尼勒斯、詹姆斯·柯登等海外明星纷纷加入，韩国国内不仅是儿童，连成年人之间也因其洗脑的旋律而引发热议。', 'SmartStudy（Pinkfong）《Baby Shark Dance》视频（2016年首次发布，2018年发展为挑战）', '可作为K内容全球走红案例引用', null, array['宝宝鲨鱼舞蹈挑战', 'Baby Shark Challenge', '아기상어 챌린지']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
