values
  ('2f6da376-12eb-4c66-88b1-96bb4b5eb07d', 'zh', 'lee-jung-ttak-liverpool-mid-table', '利中当（利物浦排中游正好）', '源自足球教练发言被夸张误译的报道，后经甘斯特改编歌曲而走红的足球梗', '2014年桑德兰主帅古斯·波耶特曾表示“如果没有苏亚雷斯，利物浦大概会是中游球队”，韩国媒体却夸张翻译报道为“利物浦排中游正好”。主播BJ甘斯特将宋大观的歌曲《流行歌》改编歌词，唱出“利中当利中当，欢快的歌”使其广泛流行。此后每逢利物浦相关话题，这句带有调侃意味的引用便成为足球社群的固定梗。', '2014年古斯·波耶特发言被夸张误译的报道，加上BJ甘斯特改编歌曲的流行', '用于足球、利物浦相关的调侃场合', null, array['利物浦排中游正好', '利中当歌', '리중딱(리버풀은 중위권이 딱이야)']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('3a805bf1-982b-451d-8a15-7348c96a0bda', 'zh', 'seo-taiji-ultraman-iya', '徐太志——《是奥特曼》', '发行首日首周销量高达90万张的徐太志2000年回归作品', '这首歌是徐太志正规6辑主打曲，将当时在韩国还很陌生的Nu Metal曲风带入主流市场。发行首日首周销量达90万张，创下历代首周销量第一的纪录，以描绘专注于一件事的“发烧友”心理的颠覆性音效引发热议。', '2000年9月8日徐太志正规6辑主打曲回归', '用于谈论徐太志回归或2000年代初摇滚、金属音乐风潮时使用', null, array['徐太志6辑主打曲', '서태지 - 울트라맨이야']::text[], '[{"text": "这张专辑首周销量简直是徐太志《是奥特曼》级别", "situation": "聊天软件"}, {"text": "那个年代徐太志回归的影响力真的太夸张了", "situation": "社交网络评论"}]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('3dc10a1e-6671-46b5-8281-8ffd149f4d5d', 'zh', 'jjilleoman-stickman', '刺人侠（찔러맨）', '以星际争霸“狂热者”为原型的火柴人Flash动画系列', '从1990年代末到2000年代初，连载于“猎奇屋（엽기하우스）”“幽默世界（유머월드）”等网站的火柴人Flash动画系列，特点是角色以在线游戏《星际争霸》中的兵种“狂热者（Zealot）”为原型。', '“찔러（찔러맨）”是笔名“북서니”创作的火柴人角色Flash动画，于1990年代末至2000年代初连载于“猎奇屋”“幽默世界”等Flash社区网站，广受欢迎。角色以《星际争霸》狂热者兵种为原型，是当时流行的火柴人动作系列的代表作之一。2000年代初“猎奇屋”衰落、火柴人Flash整体人气减退后，作者仍通过“Flash365”“주전자닷컴”等平台持续活动，2008年开设Naver社区分享设定与制作近况，但此后连载中断。', '可作为“졸라맨”系火柴人文化衍生案例提及', null, array['찔러', '찔러맨']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('8fc75170-5bff-4ac0-ad4b-146ec93e06e5', 'zh', 'squid-game-ice-jeffpeu-musical', '冻住（Jeffpeu）', '油管博主Jeffpeu将《鱿鱼游戏》第2季中“冻住！”台词改编成音乐剧风格的翻唱梗曲', '在《鱿鱼游戏》第2季中，成奇勋（李政宰饰）在“无穷花开了”游戏中一本正经地对参赛者喊出“冻住！”这句台词，油管博主Jeffpeu将其改编成音乐剧曲风翻唱。与原作阴森压抑的氛围形成强烈反差的欢快明朗编曲成为笑点，视频发布仅5天播放量便突破160万次。', '油管博主Jeffpeu制作的《鱿鱼游戏》第2季台词音乐剧改编翻唱', '用作将严肃情境幽默反转的改编梗曲', null, array['鱿鱼游戏冻住音乐剧', '얼음(제프프)']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('1e9b2e28-60a2-49d0-a2e8-96ef5fc847bd', 'zh', 'popcat', 'Pop Cat（啵嘴猫）', '猫咪盯着虫子一张一合嘴巴的视频在2020年底以点击游戏形式在韩国走红的梗', '一只名叫“燕麦片（오트밀）”的猫咪盯着虫子发出咀嚼声的视频经过剪辑，配上一张一合嘴巴的音效后，成为风靡全球的梗图。该梗于2020年12月开始在韩国走红，人气持续到2021年1月，2021年8月各国点击排名活动期间，韩国网友甚至集体点击以推高本国排名。', '剪辑自猫咪“燕麦片”视频的全球性梗，2020年12月在韩国走红', '适合用来形容单纯重复却有趣的动图', null, array['Pop Cat', '啵嘴猫', '팝캣']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('2b77cfc7-5ef3-4ae0-accc-970b6df9630c', 'zh', 'gag-concert-mappagi', '《Gag Concert》额头哥', '以撞额头肢体喜剧闻名的2006年《Gag Concert》固定环节', '从2006年8月开始播出的《Gag Concert》环节，由剃光头造型的郑宗哲表演撞额头的肢体喜剧，并留下“胡同大王额头哥！额头哥算什么东西~”这句流行语。', '该环节于2006年8月27日至2007年3月在KBS《Gag Concert》播出，由郑宗哲、金时德、金大范、朴俊亨表演拍打额头的肢体喜剧。据悉其原型是6年前在大学路小剧场演出的《混混混混是混混》，经改编为《Gag Concert》版本后大受欢迎。该环节被评价为拯救了当时处于低谷期的《Gag Concert》，还被改编成金显洙导演执导的儿童电影。当时浦项制铁外援选手丹尼尔森在庆祝进球时模仿额头哥的动作，因此获得了“丹头哥”的绰号。', '搭配肢体喜剧动作，以玩闹的方式使用', null, array['额头哥', '개그콘서트 마빡이']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('cc07b206-7c81-4780-a51e-17e139ba332f', 'zh', 'yoajeong-yogurt-ice-cream', '요아정（酸奶冰淇淋标准）', '酸奶冰淇淋品牌“요아정”及其“蜜糖搭配”在2024年社交网络上走红的梗', '以蜂巢蜜和新鲜水果配料为特色的酸奶冰淇淋品牌“요아정”，2024年夏天通过Instagram和TikTok大规模走红。一则粉丝问IU是否知道“요아정”，却被误听成“요정（妖精）”并作出回答的轶事也引发热议。该品牌在年轻女性群体中被誉为“人生甜品”，相关蜜糖搭配推荐内容层出不穷。', '品牌“酸奶冰淇淋的标准（요거트아이스크림의정석）”2024年在Instagram、TikTok上扩散', '用于谈论流行甜品、“人生好物”话题时使用', null, array['酸奶冰淇淋的标准', '요아정 꿀조합', '요아정']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
