  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('0af67ded-43c6-4273-a375-e0c5c6596dad', 'zh', 'dubai-chocolate-syndrome', '迪拜巧克力热潮', '开心果奶油巧克力通过TikTok在2024年韩国掀起的流行现象', '2023年12月，一段迪拜巧克力品牌的视频在TikTok上持续走红数月，这股热潮于2024年夏天登陆韩国。人们争相寻找内含卡塔伊夫（中东式炸面丝）和开心果奶油的巧克力，导致便利店频频缺货，这股热潮甚至一度推高了开心果的价格。', '2023年末源自迪拜的TikTok视频扩散，2024年在韩国走红', '用于谈论流行甜品、海外流行单品时使用', null, array['迪拜巧克力', '두바이초콜릿 신드롬']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
