values
  ('69528101-01d5-443d-8077-db730f6ceed1', 'zh', 'our-mom-mom-changbin-omg', '“是我们妈妈生的”梗', 'Stray Kids蒋斌把NewJeans《OMG》副歌改编翻唱而来的2023年自问自答梗', '2023年初，在Stray Kids自制内容《SKZ-TALKER》中，蒋斌把NewJeans《OMG》副歌“Oh my oh my God”改编成“是谁生得这么漂亮？是我们妈妈妈妈生的”，这一幕成为梗图。他一脸傲娇地自问自答的样子引人发笑，随后被其他偶像和粉丝纷纷模仿。', 'Stray Kids自制内容《SKZ-TALKER》第56期（约2023年1月）', '用于幽默地表达自我夸耀时使用', null, array['妈妈妈妈生的', '蒋斌妈妈妈妈生的', '우리 엄마엄마가 밈']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
